import { render, route } from "rwsdk/router";
import { defineApp } from "rwsdk/worker";
import { SyncedStateServer as BaseSyncedStateServer, syncedStateRoutes } from "rwsdk/use-synced-state/worker";
import { env } from "cloudflare:workers";

import { Document } from "@/app/document";
import { setCommonHeaders } from "@/app/headers";
import { Home } from "@/app/pages/home";
import { NotificationsPage } from "@/app/pages/notifications";

export class SyncedStateServer extends BaseSyncedStateServer {
  private loaded = false;

  constructor(state: any, env: any) {
    super(state, env);
  }

  override async fetch(request: Request) {
    if (!this.loaded) {
      try {
        const stored = await this.ctx.storage.list();
        for (const [k, v] of stored.entries()) {
          if (k.startsWith("state:")) {
            const key = k.slice(6);
            super.setState(v, key);
          }
        }
      } catch (err) {
        console.error("Error loading persisted state:", err);
      }
      this.loaded = true;
    }
    return super.fetch(request);
  }

  override setState(value: any, key: string) {
    super.setState(value, key);
    this.ctx.storage.put("state:" + key, value).catch((err: any) => {
      console.error("Error saving state:", err);
    });
  }
}

export type AppContext = {};

export default defineApp([
  setCommonHeaders(),
  ({ ctx }) => {
    // setup ctx here
    ctx;
  },
  render(Document, [
    route("/", Home),
    route("/notifications", NotificationsPage),
    ...syncedStateRoutes(() => env.SYNCED_STATE_SERVER),
  ]),
]);

"use server";

import { serverAction } from "rwsdk/server";
import { env } from "cloudflare:workers";

export interface Notification {
  id: string;
  severity: "info" | "warning" | "error";
  read: boolean;
  timestamp: number;
}

export const emitNotificationOnServer = serverAction(async (severity: "info" | "warning" | "error") => {
  const namespace = env.SYNCED_STATE_SERVER as DurableObjectNamespace<any>;
  const id = namespace.idFromName("syncedState");
  const stub = namespace.get(id);

  const currentVal = await stub.getState("notifications");
  const currentNotifications: Notification[] = Array.isArray(currentVal) ? currentVal : [];

  const newNotif: Notification = {
    id: crypto.randomUUID(),
    severity,
    read: false,
    timestamp: Date.now(),
  };

  const updated = [newNotif, ...currentNotifications];
  await stub.setState(updated, "notifications");

  return newNotif;
});

